-- ---------- Married couples' homes (only when neither of them is in a home yet) ----------
do $$
declare c uuid := (select id from churches where slug = 'graceville'); h jsonb; ids uuid[]; hid uuid;
begin
  for h in select * from jsonb_array_elements($fl$[{"id":"83c1ab90-39f4-49ff-b3bc-ef122d4f98c4","name":"Okafor household","members":[["1e31c86e-5b2a-4d90-acd8-86947fd54103","2005-11-23"],["386e8bc4-579d-4f22-9ba3-237c2724d4d7",null]]},{"id":"dcdf2ac4-8373-4a80-8b76-8d6889db24c9","name":"Bello household","members":[["a9107ac3-2d9a-449d-a1bc-75720f976717",null],["b6269f53-b807-4e38-9be1-bead48bce188",null]]},{"id":"7c4b2dda-2a50-41be-a33d-6084240cbb76","name":"Ademola household","members":[["853b5869-1f23-4d31-86ad-8602964f3868","2008-11-26"],["73826370-7f40-4483-85af-777669e536e7","2008-11-26"]]},{"id":"564c6e13-69cc-4c74-a1e6-271ee24534c0","name":"Kayode household","members":[["c875cc85-7ef2-4c6a-bdf9-7b238eb7c616","2010-12-05"],["103d3730-f232-4fec-8c7b-dcf513d98135","2010-12-05"]]},{"id":"ebb3735a-bd40-4bdc-86dd-f79d0ec0b50c","name":"Adelabu household","members":[["d5cf7039-fe97-4238-afa9-236965aa4854","2012-12-14"],["9e22c8dd-1527-4890-b6ec-3f941273ea9f","2014-12-02"]]},{"id":"03f8ffd1-2895-4150-a0cb-86651c13fce0","name":"Babatunde household","members":[["41a02ef4-3a77-49ac-b39d-a7417fce1068","2014-12-23"],["f67a7528-fbf8-4183-8e66-e4107c06f284","2014-12-23"]]},{"id":"68860944-c5c2-439e-a83d-b24e29819001","name":"Oluwanifemi household","members":[["3da60f26-76d2-479f-9a45-55f75f0c8805","2016-01-01"],["b3777ce7-0a48-49f0-bbad-eba312d05d5d","2016-01-01"]]},{"id":"177f8d27-a347-4b0a-a444-4859e83a0438","name":"Adewanbo household","members":[["c4015913-c352-4dfb-920f-9578c863d03b","2018-01-10"],["c96fb214-af92-4abe-9945-ec159f55d240","2018-01-10"]]}]$fl$::jsonb) loop
    select array_agg(m.old_id) into ids from jsonb_array_elements(h->'members') x join _fl_map m on m.new_id = x->>0;
    if coalesce(array_length(ids, 1), 0) <> jsonb_array_length(h->'members') then continue; end if;
    if exists (select 1 from people where id = any (ids) and household_id is not null) then continue; end if;
    hid := gen_random_uuid();
    insert into households (id, church_id, name) values (hid, c, h->>'name');
    update people p set household_id = hid,
           anniversary = coalesce(p.anniversary, (pg_temp.shift(to_jsonb(x->>1)) #>> '{}')::date)
      from jsonb_array_elements(h->'members') x join _fl_map m on m.new_id = x->>0
     where p.id = m.old_id;
  end loop;
end $$;

