insert into counsel_requests (id, church_id, person_id, handler_id, status, data)
select id, church_id, person_id, handler_id, status, data from jsonb_populate_recordset(null::counsel_requests, pg_temp.fl($fl$[{"id":"cs3","church_id":"19751155-65fe-4b57-bf0f-5d548bcabeba","person_id":"3b9d2dd0-7b6a-40bd-ade3-7d1416aa58cb","handler_id":"b3777ce7-0a48-49f0-bbad-eba312d05d5d","status":"referred","data":{"id":"cs3","personId":"3b9d2dd0-7b6a-40bd-ade3-7d1416aa58cb","at":"2026-11-21T06:56:51.943Z","urgency":"soon","description":"","tags":["Marriage"],"status":"referred","handlerId":"b3777ce7-0a48-49f0-bbad-eba312d05d5d","log":[{"at":"2026-11-21T06:56:51.943Z","byId":"3b9d2dd0-7b6a-40bd-ade3-7d1416aa58cb","text":"Asked for counselling"},{"at":"2026-11-22T00:56:51.943Z","byId":"1e31c86e-5b2a-4d90-acd8-86947fd54103","text":"Referred to Ronke Adeyemi (Family Life)"}]}}]$fl$::jsonb))
