insert into counsel_private (id, church_id, request_id, body)
select id, church_id, request_id, body from jsonb_populate_recordset(null::counsel_private, pg_temp.fl($fl$[{"id":"cs3","church_id":"19751155-65fe-4b57-bf0f-5d548bcabeba","request_id":"cs3","body":"We've been married three years and we've stopped talking. We want help before it gets worse."}]$fl$::jsonb))
on conflict do nothing;

-- ---------- The Family Life team meeting and who's coming ----------
update groups g set extra = jsonb_set(coalesce(g.extra, '{}'::jsonb), '{meetings}',
       coalesce(g.extra->'meetings', '[]'::jsonb) || pg_temp.fl($fl$[{"id":"dm-fam1","title":"Family Life team meeting","kind":"regular","weekday":6,"every":"month","time":"16:00","mode":"hybrid","venue":"Family Life room","link":"https://meet.google.com/family-life-team","notes":"Plan the Couples' Dinner and the next Marriage Preparation class.","updatedAt":"2026-11-22T10:56:51.942Z","byId":"b3777ce7-0a48-49f0-bbad-eba312d05d5d"}]$fl$::jsonb))
 where g.id = (select old_id from _fl_map where new_id = 'fbd51cdd-1013-4576-a364-1a1b057d0af6')
   and not exists (select 1 from jsonb_array_elements(coalesce(g.extra->'meetings', '[]'::jsonb)) x where x->>'id' = 'dm-fam1');
insert into meeting_rsvps (id, church_id, person_id, kind, ref_id, data)
select id, church_id, person_id, kind, ref_id, data from jsonb_populate_recordset(null::meeting_rsvps, pg_temp.fl($fl$[{"id":"dept|dm-fam1|2026-11-28|p120","church_id":"19751155-65fe-4b57-bf0f-5d548bcabeba","person_id":"d7f972a6-a2aa-4d61-982f-8f150eab4de5","kind":"dept","ref_id":"fbd51cdd-1013-4576-a364-1a1b057d0af6","data":{"id":"dept|dm-fam1|2026-11-28|p120","personId":"d7f972a6-a2aa-4d61-982f-8f150eab4de5","kind":"dept","refId":"fbd51cdd-1013-4576-a364-1a1b057d0af6","meetingId":"dm-fam1","date":"2026-11-28","answer":"yes","at":"2026-11-22T20:56:51.942Z"}},{"id":"dept|dm-fam1|2026-11-28|p131","church_id":"19751155-65fe-4b57-bf0f-5d548bcabeba","person_id":"a8f074ae-d831-4111-99e8-d8b46d66b343","kind":"dept","ref_id":"fbd51cdd-1013-4576-a364-1a1b057d0af6","data":{"id":"dept|dm-fam1|2026-11-28|p131","personId":"a8f074ae-d831-4111-99e8-d8b46d66b343","kind":"dept","refId":"fbd51cdd-1013-4576-a364-1a1b057d0af6","meetingId":"dm-fam1","date":"2026-11-28","answer":"no","at":"2026-11-22T20:56:51.942Z"}}]$fl$::jsonb))
