-- ---------- The Couples' Dinner: goals, targets and committee (what the event already has is kept) ----------
select set_config('request.jwt.claim.sub', coalesce((select id::text from auth.users where email = 'lead.pastor@graceville.example'), ''), true);
update events e set data = pg_temp.fl($fl${"goals":"A warm, unhurried evening that strengthens marriages and draws in couples who don't yet attend.","objectives":["60 couples, with at least 10 visiting couples","Every couple leaves with the Marriage Enrichment dates"],"targetBudget":900000,"regTarget":60,"committee":{"members":[{"personId":"b3777ce7-0a48-49f0-bbad-eba312d05d5d","role":"Committee head"},{"personId":"d7f972a6-a2aa-4d61-982f-8f150eab4de5","role":"Hospitality and menu","perms":["budget"],"addedById":"1e31c86e-5b2a-4d90-acd8-86947fd54103","addedAt":"2026-11-19T06:56:51.942Z"},{"personId":"a8f074ae-d831-4111-99e8-d8b46d66b343","role":"Decor and seating","addedById":"1e31c86e-5b2a-4d90-acd8-86947fd54103","addedAt":"2026-11-19T06:56:51.942Z"},{"personId":"051a953e-5b57-4f8d-a445-3fcaabd124a6","role":"Programme and music","addedById":"1e31c86e-5b2a-4d90-acd8-86947fd54103","addedAt":"2026-11-19T06:56:51.942Z"}],"headId":"b3777ce7-0a48-49f0-bbad-eba312d05d5d","assistantId":"d7f972a6-a2aa-4d61-982f-8f150eab4de5","financeLeadId":"d7f972a6-a2aa-4d61-982f-8f150eab4de5","meetings":[{"id":"cmc1","date":"2026-11-29","time":"19:30","mode":"virtual","link":"https://meet.google.com/couples-dinner","agenda":"Venue options, menu tasting, ticket price","byId":"b3777ce7-0a48-49f0-bbad-eba312d05d5d","at":"2026-11-23T00:56:51.942Z"}],"messages":[{"id":"cmc-m1","byId":"853b5869-1f23-4d31-86ad-8602964f3868","at":"2026-11-20T06:56:51.942Z","to":"heads","text":"Let's keep it affordable so young couples can come. Please confirm a venue before you publish."}]}}$fl$::jsonb) || e.data
 where e.church_id = (select id from churches where slug = 'graceville') and e.id = 'ev-couples';
update events e set data = jsonb_set(e.data, '{questions}', coalesce(e.data->'questions', '[]'::jsonb) || coalesce((
         select jsonb_agg(x) from jsonb_array_elements($fl$[{"id":"gender","label":"Gender","type":"choice","options":["Male","Female"],"perPerson":true},{"id":"diet","label":"Any food needs or allergies?","type":"text","perPerson":true}]$fl$::jsonb) x
          where not exists (select 1 from jsonb_array_elements(coalesce(e.data->'questions', '[]'::jsonb)) y where y->>'id' = x->>'id')), '[]'::jsonb))
 where e.church_id = (select id from churches where slug = 'graceville') and e.id = 'ev-couples';
select set_config('request.jwt.claim.sub', '', true);

commit;

do $$ begin raise notice 'Family Life is ready: % courses, % couples in courses, % married homes.',
  (select count(*) from programmes p join churches c on c.id = p.church_id where c.slug = 'graceville' and p.data->>'owner' = 'family'),
  (select count(*) / 2 from enrolments e join churches c on c.id = e.church_id where c.slug = 'graceville' and e.data ? 'partnerId'),
  (select count(*) from households h join churches c on c.id = h.church_id where c.slug = 'graceville'); end $$;
